UPDATE lessons SET title='Year 8, Week 22, Lesson 1: Light and reflection', data=json_patch(data,'{"child_mission":"Stage 4 Science develops evidence-based thinking for light and reflection. Students ask testable questions, record observations, and link claims to data. Catalogue alignment uses SC4-WS-01.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same science idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nFor light and reflection, write question → evidence → claim, naming what was observed or measured.\n\nFEEDBACK\nStrong answer: evidence is specific; claim does not overreach the data.\n\nWATCH FOR\nTreating light and reflection as a guess, or changing multiple variables at once without noting it.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nIndependently complete a substantial task on light and reflection: plan or analyse an investigation, record evidence, and write a five-sentence evaluation of the claim’s limits.\n\nWrite a short reflection naming one observation, criterion or step you corrected and why.","interactive_activities":null,"learning_area":"Science","learning_intention":"Stage 4 Science develops evidence-based thinking for light and reflection. Students ask testable questions, record observations, and link claims to data. Catalogue alignment uses SC4-WS-01.","lesson_number":1,"lesson_role":"Investigate","materials":["Paper or typed answer space","Pencil","Optional: safe everyday objects for observation"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["SC4-WS-01"],"parent_notes":"Parent: Marking guidance for the independent task: Independently complete a substantial task on light and reflection: plan or analyse an investigation, record evidence, and write a five-sentence evaluation of the claim’s limits. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new object/context, two named observations, claim about light linked to that evidence.\n\nParent: Written model 2: Sample misconception: Treating light and reflection as a guess, or changing multiple variables at once without noting it.. Correction: Strong answer: evidence is specific; with evidence.\n\nParent: Likely misconception: Treating light and reflection as a guess, or changing multiple variables at once without noting it. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Investigate or describe a fresh example (not the worked objects) that uses light. Record evidence and explain how it supports your claim.\n\nParent: Short-answer focus 2: Name one science misconception about light, correct it with evidence, and say why the correction works.\n\nParent: Marking notes: Accept a new example with named observations and a claim–evidence link about light. Reject title-only labels with no observation. / Accept a misconception plus corrected claim and evidence reason for light. Reject wording changes that leave the same error..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for light. The other choices miss a key step or use a common mistake.","options":["evidence is specific; claim does not overreach the data.","Treating light and reflection as a guess, or changing multiple variables at once without noting it.","Ignore the observation or criteria and invent a more exciting result.","Copy the model objects and call that independent work."],"question":"For light and reflection, write question → evidence → claim, naming what was observed or measured. Which response is most accurate?","type":"multiple_choice"},{"correct_index":2,"explanation":"This is the misconception to avoid for light; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["evidence is specific; claim does not overreach the data.","Careful use of reflection with clear evidence.","Treating light and reflection as a guess, or changing multiple variables at once without noting it.","Stage 4 Science develops evidence-based thinking for light and reflection."],"question":"Which statement is a common mistake when working with light?","type":"multiple_choice"},{"correct_index":3,"explanation":"Understanding is shown by new evidence and a named reflection, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Repeat the worked example wording with no new evidence.","Treating light and reflection as a guess, or changing multiple variables at once without noting it.","Name reflection only, without linking it to light.","Apply light to new material and name the reflection used."],"question":"Which response best applies light with new evidence?","type":"multiple_choice"},{"correct_index":3,"explanation":"Trustworthy science claims rest on observable evidence linked to the claim. The other choices miss a key step or use a common mistake.","options":["Decide from which object looks most exciting.","Copy a label from the lesson title with no observation.","Treating light and reflection as a guess, or changing multiple variables at once without noting it.","Use observable features or measurements as evidence, not appearance alone."],"question":"New examples: steam from a kettle, a germinating bean, a plastic dinosaur, a granite pebble. Which claim about light is most trustworthy?","type":"multiple_choice"},{"correct_index":1,"explanation":"Science claims need named observations linked to the claim. The other choices miss a key step or use a common mistake.","options":["Treating light and reflection as a guess, or changing multiple variables at once without noting it.","A named observation plus how it supports the claim.","A longer story with no observation.","A label copied from the title with no evidence."],"question":"Which record best supports a science claim about light?","type":"multiple_choice"},{"correct_index":0,"explanation":"The strongest choice applies the taught idea about light with evidence. The other choices miss a key step or use a common mistake.","options":["evidence is specific; claim does not overreach the data.","Treating light and reflection as a guess, or changing multiple variables at once without noting it.","Change several conditions at once so something happens faster.","Ignore measurements and decide by which looks nicer."],"question":"Using this science idea — Stage 4 Science develops evidence-based thinking for light and reflection. — which choice is strongest?","type":"multiple_choice"},{"correct_index":2,"explanation":"Fair tests change one variable, control the rest, and use recorded evidence. The other choices miss a key step or use a common mistake.","options":["Stop early when you like the first result.","Ignore measurements and decide by which looks nicer.","Identify the independent variable, control the rest, and record repeatable measurements.","Change several conditions at once so something happens faster."],"question":"Which investigation design best tests an idea about light?","type":"multiple_choice"},{"correct_index":0,"explanation":"Scientific predictions stay open to new observations rather than protecting a first guess. The other choices miss a key step or use a common mistake.","options":["If the observed feature changes, the claim about light should change with it.","Any exciting story about the object must be true.","Treating light and reflection as a guess, or changing multiple variables at once without noting it.","Results that disagree with the first guess should be discarded."],"question":"Which prediction about light can be checked with evidence?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept a new example with named observations and a claim–evidence link about light. Reject title-only labels with no observation.","question":"Investigate or describe a fresh example (not the worked objects) that uses light. Record evidence and explain how it supports your claim.","sample_answer":"Sample: new object/context, two named observations, claim about light linked to that evidence.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception plus corrected claim and evidence reason for light. Reject wording changes that leave the same error.","question":"Name one science misconception about light, correct it with evidence, and say why the correction works.","sample_answer":"Sample misconception: Treating light and reflection as a guess, or changing multiple variables at once without noting it.. Correction: Strong answer: evidence is specific; with evidence.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s4-sci-y8-w22-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA Science and Technology alignment using catalogue outcome codes; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S4","stage_hints":{"accept":["Today you will practise light.","Read the mission before you start observing, designing or testing.","Keep the property, criterion or variable you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the observation, criterion or step that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore observations, criteria or fair tests.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread labels, measurements and sequence of steps.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact observation, criterion or test step before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key observations or criteria.","Say what each observation or criterion shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or method, not only how neat the drawing looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh object or context that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new objects or data."]},"subject":"Physical World","success_criteria":["I can use light with a specific example from this lesson.","I can identify reflection and explain why it matters.","I can practise evidence independently on a new prompt.","I can notice fair test needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":2,"explanation":"Stage 4 Science develops evidence-based thinking for light and reflection.","options":["An answer copied without understanding.","A guess with no evidence.","Stage 4 Science develops evidence-based thinking for light and reflection.","A claim unrelated to the observation, test or criteria."],"question":"Which choice best shows accurate use of this idea about light?","type":"multiple_choice"},"example":"WORKED MODEL\nExample for Light and reflection: state the question/variable, describe evidence, and make a cautious claim. Weak: a claim with no observation.\n\nTRY FIRST\nFor light and reflection, write question → evidence → claim, naming what was observed or measured.\n\nFEEDBACK\nStrong answer: evidence is specific; claim does not overreach the data.","explain":"Stage 4 Science develops evidence-based thinking for light and reflection. Students ask testable questions, record observations, and link claims to data. Catalogue alignment uses SC4-WS-01.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen, measured or tested against criteria.\n\nHOW TO WORK\nRead the worked example and name the observations, properties, criteria or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer. For practical technology work, follow teacher safety rules for tools, food and devices.","icon":"📖","notice":"Treating light and reflection as a guess, or changing multiple variables at once without noting it. Correct the claim, criteria use or method, not just the neatness of the diagram.","title":"Understand and model","visual":[{"alt":"Light and reflection.","caption":"Claim matches data.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Question</text><text x=\"28\" y=\"78\">Light and reflection</text><text x=\"358\" y=\"42\">Evidence</text><text x=\"358\" y=\"78\">observation</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which observation or criterion matters most.","who":"pip"},{"text":"Name the observations, criteria or test steps that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Example for Light and reflection: state the question/variable, describe evidence, and make a cautious claim. Weak: a cla Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which observation or criterion matters most.\nJuno: Name the observations, criteria or test steps that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Example for Light and reflection: state the question/variable, describe evidence, and make a cautious claim. Weak: a cla Then write your own evidence."}}]},{"check":{"correct_index":2,"explanation":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim. Supported records follow the actual observations, criteria and purpose of the task. The other choices miss a key step or use a common mistake.","options":["An answer copied without understanding.","A guess with no evidence.","Make the science idea visible: name the observation, source or example you used and say why it supports the claim.","A claim unrelated to the observation, test or criteria."],"question":"Which choice best shows accurate use of this idea about light?","type":"multiple_choice"},"example":"WORKED MODEL\nExample for Light and reflection: state the question/variable, describe evidence, and make a cautious claim. Weak: a claim with no observation. Look at each observation, source detail or example that carries the idea.\n\nTRY FIRST\nList the key observations, sources or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen, measured or tested against criteria.\n\nHOW TO WORK\nRead the worked example and name the observations, properties, criteria or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer. For practical technology work, follow teacher safety rules for tools, food and devices.","icon":"📖","notice":"Writing only a final label without evidence does not show science thinking. Correct the claim, criteria use or method, not just the neatness of the diagram.","title":"Show the evidence","visual":[{"alt":"Fair thinking.","caption":"Note limits.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Weak</text><text x=\"28\" y=\"78\">guess only</text><text x=\"358\" y=\"42\">Strong</text><text x=\"358\" y=\"78\">evidence link</text></g></svg>"}]},{"check":{"correct_index":3,"explanation":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim. Supported records follow the actual observations, criteria and purpose of the task. The other choices miss a key step or use a common mistake.","options":["A claim unrelated to the observation, test or criteria.","An answer copied without understanding.","A guess with no evidence.","Use an intentionally incorrect claim as a comparison."],"question":"Which choice best shows accurate use of this idea about light?","type":"multiple_choice"},"example":"WORKED MODEL\nTreating light and reflection as a guess, or changing multiple variables at once without noting it. Here is a more productive model: Example for Light and reflection: state the question/variable, describe evidence, and make a cautious claim. Weak: a claim with no observation.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nStrong answer: evidence is specific; claim does not overreach the data.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen, measured or tested against criteria.\n\nHOW TO WORK\nRead the worked example and name the observations, properties, criteria or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer. For practical technology work, follow teacher safety rules for tools, food and devices.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. Treating light and reflection as a guess, or changing multiple variables at once without noting it. Correct the claim, criteria use or method, not just the neatness of the diagram.","title":"Test a misconception"},{"check":{"correct_index":3,"explanation":"Use the same science idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence. Supported records follow the actual observations, criteria and purpose of the task. The other choices miss a key step or use a common mistake.","options":["A claim unrelated to the observation, test or criteria.","An answer copied without understanding.","A guess with no evidence.","Use the same science idea on a new place, person, source or context, not a copy of the worked example."],"question":"Which choice best shows accurate use of this idea about light?","type":"multiple_choice"},"example":"WORKED MODEL\nStage 4 Science develops evidence-based thinking for light and reflection. Students ask testable questions, record observations, and link claims to data. Catalogue alignment uses SC4-WS-01. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInquire into or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same science idea as the model, but contain different evidence.","explain":"Use the same science idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen, measured or tested against criteria.\n\nHOW TO WORK\nRead the worked example and name the observations, properties, criteria or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer. For practical technology work, follow teacher safety rules for tools, food and devices.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim, criteria use or method, not just the neatness of the diagram.","title":"Transfer to a new investigation"}],"title":"Year 8, Week 22, Lesson 1: Light and reflection","unit_number":5,"unit_title":"Waves, light and sound","week":22,"week_in_unit":2,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample for Light and reflection: state the question/variable, describe evidence, and make a cautious claim. Weak: a claim with no observation.\n\nWrite what makes this example accurate, naming the observations, criteria, properties or test steps used.","worked_visuals":[{"alt":"Light and reflection.","caption":"Claim matches data.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Question</text><text x=\"28\" y=\"78\">Light and reflection</text><text x=\"358\" y=\"42\">Evidence</text><text x=\"358\" y=\"78\">observation</text></g></svg>"},{"alt":"Fair thinking.","caption":"Note limits.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Weak</text><text x=\"28\" y=\"78\">guess only</text><text x=\"358\" y=\"42\">Strong</text><text x=\"358\" y=\"78\">evidence link</text></g></svg>"}],"year_level":"Year 8"}') WHERE seed_key='s4-sci-y8-w22-l1' AND family_id IS NULL;
